
import type { GiftCardProductConfigurationInput } from './GiftCardProductConfigurationInput.js';
import type { ImageInput } from './ImageInput.js';
import type { MoneyValueInput } from './MoneyValueInput.js';

export type ProductVariantInput = { "available_for_sale"?: never; "barcode"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "current_delivery_profile_revision_id"?: never; "delivery_configuration_reason"?: never; "delivery_configuration_status"?: never; "delivery_profile_id"?: string; "effective_images"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Gift card issuance terms. face_value_money is the reference denomination; unit_price_money is its price. Custom amounts use that price-to-value ratio, rounded to the nearest cent with ties up. */ "gift_card_configuration"?: GiftCardProductConfigurationInput; "images": Array<ImageInput>; "images_inherited"?: never; /** The inventory item this variant consumes. Present exactly when inventory_tracking is tracked. Several variants may share one inventory item. */ "inventory_item_id"?: string; "inventory_tracking"?: never; /** Flint line-item tax category. */ "line_item_tax_category"?: "general" | "physical_goods" | "digital_goods" | "software" | "saas" | "services" | "professional_services" | "food" | "prepared_food" | "clothing" | "medical_goods" | "admission"; "merchant_id"?: never; "metadata"?: Record<string, string>; "modifier_set"?: never; /** Attached modifier set. Send null on update to remove it. pattern: ^ms_[0-9A-HJKMNP-TV-Z]{26}$. */ "modifier_set_id": string | null; "name"?: string; /** Format: int32. */ "position": number; "product_id"?: never; "selected_options"?: never; "sku"?: string; "status": "active" | "inactive" | "archived"; "taxable"?: boolean; "unit_price_money": MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; "variant_id"?: never; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version"?: never; };
